// The native packages' generated files, written from the sources the web reads: the palette
// (DS1/1-root/palette.ts), the measures (DS1/1-root/measures.ts), the surface colours of the
// component tokens (DS1/1-root/component-tokens.css) and the icon names (DS1/x-icon).
// scripts/write-native-tokens.ts writes them; tests/native-tokens.test.ts fails when a committed
// file is stale. Never edit a generated file: change its source and run the script.
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { palette } from '../DS1/1-root/palette';
import { measures } from '../DS1/1-root/measures';
import { LANGUAGES, LANGUAGE_METADATA, fallbackLanguages } from '../DS1/0-face/languages';

const root = fileURLToPath(new URL('..', import.meta.url));
const read = (path: string) => readFileSync(root + path, 'utf8');
export const appleGenerated = 'native/apple/Sources/DS1/Generated';

const header = (source: string) =>
  `// Generated by scripts/write-native-tokens.ts from ${source}.\n// Do not edit: change the source and run \`vp run native:tokens\`.\n`;

/** `Tuned red` → `tunedRed`, `shield-alt` → `shieldAlt`, `1x` → `icon1x`. */
export function swiftName(words: string, prefix = 'icon') {
  const parts = words.split(/[^A-Za-z0-9]+/).filter(Boolean);
  const name = parts.map((p, i) => (i ? p[0].toUpperCase() : p[0].toLowerCase()) + p.slice(1)).join('');
  return /^[0-9]/.test(name) ? prefix + name : name;
}
const keywords = new Set(['default', 'repeat', 'in', 'return', 'case', 'import', 'switch', 'class', 'struct', 'enum', 'protocol', 'func', 'var', 'let', 'if', 'else', 'for', 'while', 'do', 'break', 'continue', 'true', 'false', 'nil', 'self', 'super', 'init', 'is', 'as', 'try', 'throw', 'where', 'operator', 'extension', 'internal', 'public', 'private', 'static', 'subscript', 'typealias', 'guard', 'defer', 'fallthrough', 'inout', 'Type', 'Any', 'Self']);
const identifier = (name: string) => (keywords.has(name) ? `\`${name}\`` : name);
const hex = (value: string) => `0x${value.slice(1).toLowerCase()}`;

/** A colour as written in the CSS: `#rrggbb` or `#rrggbbaa`. */
type Css = { hex: string; alpha: number };
function colour(value: string): Css {
  const m = /^#([0-9a-f]{6})([0-9a-f]{2})?$/i.exec(value.trim());
  if (!m) throw new Error(`Not a colour: ${value}`);
  return { hex: `#${m[1].toLowerCase()}`, alpha: m[2] ? Math.round((parseInt(m[2], 16) / 255) * 1000) / 1000 : 1 };
}

/** The custom properties of the first `:root` block of a stylesheet. */
function rootProperties(css: string) {
  const start = css.indexOf(':root {');
  const block = css.slice(start, css.indexOf('\n}', start));
  const properties = new Map<string, string>();
  for (const m of block.replace(/\/\*[\s\S]*?\*\//g, '').matchAll(/(--[\w-]+):\s*([^;]+);/g)) properties.set(m[1], m[2].replace(/\s+/g, ' ').trim());
  return properties;
}

/** A property's light and dark values, following `var()` and `light-dark()`. */
function lightDark(properties: Map<string, string>, name: string): [Css, Css] {
  const resolve = (value: string): string => {
    const v = /^var\((--[\w-]+)\)$/.exec(value.trim());
    if (!v) return value.trim();
    const next = properties.get(v[1]);
    if (!next) throw new Error(`${v[1]} is not declared`);
    return resolve(next);
  };
  const value = resolve(properties.get(name) ?? (() => { throw new Error(`${name} is not declared`); })());
  const ld = /^light-dark\((.+)\)$/.exec(value);
  if (!ld) return [colour(value), colour(value)];
  // The comma between the two values, outside any parentheses of their own.
  let depth = 0;
  let split = -1;
  for (let i = 0; i < ld[1].length && split < 0; i++) {
    if (ld[1][i] === '(') depth++;
    else if (ld[1][i] === ')') depth--;
    else if (ld[1][i] === ',' && !depth) split = i;
  }
  return [colour(resolve(ld[1].slice(0, split))), colour(resolve(ld[1].slice(split + 1)))];
}

/** The surfaces the component tokens define, as their Swift names. */
export const surfaces: [string, string, string][] = [
  ['paper', '--ds-paper', 'The page.'],
  ['text', '--ds-text-color', 'Text.'],
  ['textMuted', '--ds-text-color-muted', 'Quieter text.'],
  ['title', '--ds-title-color', 'Titles and table headers.'],
  ['danger', '--ds-danger-color', 'Text that reports a failure or warns of a loss.'],
  ['warning', '--ds-warning-color', 'Text that asks for care before something goes wrong.'],
  ['border', '--ds-border-color', 'Outlines.'],
  ['fill', '--ds-fill', 'A control on the paper.'],
  ['fillHover', '--ds-fill-hover', 'A control under the pointer.'],
  ['focusRing', '--ds-focus-ring', 'The focus ring.'],
  ['accent', '--ds-accent-color', 'The accent: a primary button, a meaningful state.'],
  ['onAccent', '--ds-button-text-color-on-accent', 'Text on the accent.'],
  ['inputBackground', '--ds-input-background', 'A field.'],
  ['inputText', '--ds-input-color', 'Text in a field.'],
  ['inputPlaceholder', '--ds-input-placeholder-color', 'A field’s placeholder.'],
];

function swiftColour(light: Css, dark: Css) {
  const alpha = light.alpha !== 1 || dark.alpha !== 1 ? `, lightOpacity: ${light.alpha}, darkOpacity: ${dark.alpha}` : '';
  return `DS1Color(light: ${hex(light.hex)}, dark: ${hex(dark.hex)}${alpha})`;
}

export function paletteSwift() {
  const lines = [header('DS1/1-root/palette.ts and the surfaces of DS1/1-root/component-tokens.css'), 'extension DS1Color {'];
  const entries: string[] = [];
  for (const c of palette()) {
    const name = swiftName(c.name);
    const pastel = swiftName(c.pastelName);
    lines.push(`    /// ${c.name}: ${c.hex}, ${c.dark} in dark mode.`);
    lines.push(`    public static let ${identifier(name)} = ${swiftColour(colour(c.hex), colour(c.dark))}`);
    lines.push(`    /// ${c.pastelName}: ${c.pastel}, dimmed to ${c.dim} in dark mode.`);
    lines.push(`    public static let ${identifier(pastel)} = ${swiftColour(colour(c.pastel), colour(c.dim))}`);
    entries.push(`        DS1PaletteEntry(name: ${JSON.stringify(c.name)}, colour: .${identifier(name)}, pastelName: ${JSON.stringify(c.pastelName)}, pastel: .${identifier(pastel)}, ink: ${c.ink}),`);
  }
  const properties = rootProperties(read('DS1/1-root/component-tokens.css'));
  lines.push('');
  for (const [name, token, doc] of surfaces) {
    const [light, dark] = lightDark(properties, token);
    lines.push(`    /// ${doc} \`${token}\`.`);
    lines.push(`    public static let ${identifier(name)} = ${swiftColour(light, dark)}`);
  }
  lines.push('', '    /// The palette in its order around the wheel, then the inks, lightest first.', '    public static let palette: [DS1PaletteEntry] = [', ...entries, '    ]', '}', '');
  return lines.join('\n');
}

export function metricsSwift() {
  const lines = [header('DS1/1-root/measures.ts'), 'import CoreGraphics', '', '/// Design system 1’s measures at a scale of 1, in points. Multiply a length by `DS1Scale`.', 'public enum DS1Metrics {'];
  const walk = (value: Record<string, unknown>, path: string[]) => {
    for (const [key, v] of Object.entries(value)) {
      const name = swiftName([...path, key].join(' '));
      if (typeof v === 'object' && v) walk(v as Record<string, unknown>, [...path, key]);
      else if (key === 'decimals') lines.push(`    public static let ${identifier(name)}: Int = ${v}`);
      else lines.push(`    public static let ${identifier(name)}: CGFloat = ${v}`);
    }
  };
  walk(measures as unknown as Record<string, unknown>, []);
  lines.push('}', '');
  return lines.join('\n');
}

export function iconNames() {
  return readdirSync(root + 'DS1/x-icon').filter(f => f.endsWith('.svg')).map(f => f.slice(0, -4)).sort();
}

export function iconsSwift() {
  const lines = [header('the files in DS1/x-icon'), '/// Every icon in Design system 1’s library, by its file name.', 'public enum DS1IconName: String, CaseIterable, Sendable {'];
  for (const name of iconNames()) {
    const swift = swiftName(name);
    lines.push(swift === name ? `    case ${identifier(swift)}` : `    case ${identifier(swift)} = ${JSON.stringify(name)}`);
  }
  lines.push('}', '');
  return lines.join('\n');
}

/** Every generated Swift file, by its path in the repository. */
export function appleTokenFiles(): Record<string, string> {
  return {
    [`${appleGenerated}/Palette.swift`]: paletteSwift(),
    [`${appleGenerated}/Metrics.swift`]: metricsSwift(),
    [`${appleGenerated}/Icons.swift`]: iconsSwift(),
    [`${appleGenerated}/Languages.swift`]: languagesSwift(),
    [`${appleGenerated}/Words.swift`]: wordsSwift(),
  };
}

/* ------------------------------------------------------------------------------------------
 * The Kotlin package's generated files: the same names as the Swift package's, so an app on
 * both platforms says `appleGreen`, `square` and `shieldAlt` in either.
 * ---------------------------------------------------------------------------------------- */

export const androidGenerated = 'native/android/ds1/src/main/kotlin/com/designsystem1/ds1/generated';
const kotlinKeywords = new Set(['as', 'break', 'class', 'continue', 'do', 'else', 'false', 'for', 'fun', 'if', 'in', 'interface', 'is', 'null', 'object', 'package', 'return', 'super', 'this', 'throw', 'true', 'try', 'typealias', 'typeof', 'val', 'var', 'when', 'while',
  // Modifiers, which a declaration cannot start with unescaped.
  'abstract', 'actual', 'annotation', 'companion', 'const', 'crossinline', 'data', 'enum', 'expect', 'external', 'final', 'infix', 'inline', 'inner', 'internal', 'lateinit', 'noinline', 'open', 'operator', 'out', 'override', 'private', 'protected', 'public', 'reified', 'sealed', 'suspend', 'tailrec', 'value', 'vararg']);
const kotlinIdentifier = (name: string) => (kotlinKeywords.has(name) ? `\`${name}\`` : name);
/** Names an enum already has for itself, which an entry may not take. */
const enumMembers = new Set(['name', 'ordinal', 'values', 'valueOf', 'entries']);
const kotlinHeader = (source: string) =>
  `// Generated by scripts/write-native-tokens.ts from ${source}.\n// Do not edit: change the source and run \`vp run native:tokens\`.\n`;
const kotlinHex = (value: string) => `0x${value.slice(1).toLowerCase()}`;

function kotlinColour(light: Css, dark: Css) {
  const alpha = light.alpha !== 1 || dark.alpha !== 1 ? `, lightAlpha = ${light.alpha}f, darkAlpha = ${dark.alpha}f` : '';
  return `DS1Color(light = ${kotlinHex(light.hex)}, dark = ${kotlinHex(dark.hex)}${alpha})`;
}

export function paletteKotlin() {
  const lines = [kotlinHeader('DS1/1-root/palette.ts and the surfaces of DS1/1-root/component-tokens.css'), 'package com.designsystem1.ds1', '', '/** Design system 1’s colours: the palette and its pastels, then the surfaces of the component tokens. */', 'object DS1Colors {'];
  const entries: string[] = [];
  for (const c of palette()) {
    const name = kotlinIdentifier(swiftName(c.name));
    const pastel = kotlinIdentifier(swiftName(c.pastelName));
    lines.push(`    /** ${c.name}: ${c.hex}, ${c.dark} in dark mode. */`);
    lines.push(`    val ${name} = ${kotlinColour(colour(c.hex), colour(c.dark))}`);
    lines.push(`    /** ${c.pastelName}: ${c.pastel}, dimmed to ${c.dim} in dark mode. */`);
    lines.push(`    val ${pastel} = ${kotlinColour(colour(c.pastel), colour(c.dim))}`);
    entries.push(`        DS1PaletteEntry(${JSON.stringify(c.name)}, ${name}, ${JSON.stringify(c.pastelName)}, ${pastel}, ink = ${c.ink}),`);
  }
  const properties = rootProperties(read('DS1/1-root/component-tokens.css'));
  lines.push('');
  for (const [name, token, doc] of surfaces) {
    const [light, dark] = lightDark(properties, token);
    lines.push(`    /** ${doc} \`${token}\`. */`);
    lines.push(`    val ${kotlinIdentifier(name)} = ${kotlinColour(light, dark)}`);
  }
  lines.push('', '    /** The palette in its order around the wheel, then the inks, lightest first. */', '    val palette: List<DS1PaletteEntry> = listOf(', ...entries, '    )', '}', '');
  return lines.join('\n');
}

export function metricsKotlin() {
  const lines = [kotlinHeader('DS1/1-root/measures.ts'), 'package com.designsystem1.ds1', '', '/** Design system 1’s measures at a scale of 1, in dp. Multiply a length by `DS1Scale`. */', 'object DS1Metrics {'];
  const walk = (value: Record<string, unknown>, path: string[]) => {
    for (const [key, v] of Object.entries(value)) {
      const name = kotlinIdentifier(swiftName([...path, key].join(' ')));
      if (typeof v === 'object' && v) walk(v as Record<string, unknown>, [...path, key]);
      else if (key === 'decimals') lines.push(`    const val ${name}: Int = ${v}`);
      else lines.push(`    const val ${name}: Float = ${v}f`);
    }
  };
  walk(measures as unknown as Record<string, unknown>, []);
  lines.push('}', '');
  return lines.join('\n');
}

/** An icon's Kotlin entry name: its Swift name, kept clear of the enum's own members. */
export function kotlinIconName(name: string) {
  const swift = swiftName(name);
  return enumMembers.has(swift) ? `icon${swift[0].toUpperCase()}${swift.slice(1)}` : kotlinIdentifier(swift);
}

export function iconsKotlin() {
  const lines = [kotlinHeader('the files in DS1/x-icon'), 'package com.designsystem1.ds1', '', 'import androidx.annotation.DrawableRes', '', '/** Every icon in Design system 1’s library, by its file name, with its vector drawable. */', 'enum class DS1IconName(val fileName: String, @DrawableRes val drawable: Int) {'];
  for (const name of iconNames()) {
    const resource = `ds1_icon_${name.replace(/[^A-Za-z0-9]+/g, '_').toLowerCase()}`;
    lines.push(`    ${kotlinIconName(name)}(${JSON.stringify(name)}, R.drawable.${resource}),`);
  }
  lines.push('    ;', '', '    companion object {', '        /** The icon with this file name, or null. */', '        fun of(fileName: String): DS1IconName? = entries.firstOrNull { it.fileName == fileName }', '    }', '}', '');
  return lines.join('\n');
}

/** The shared words (DS1/0-face/translations), each language's own table, keyed by the English words. */
export function sharedWordTables(): Record<string, Record<string, string>> {
  const tables: Record<string, Record<string, string>> = {};
  for (const file of readdirSync(root + 'DS1/0-face/translations').filter(f => f.endsWith('.json')).sort()) {
    const json = JSON.parse(read(`DS1/0-face/translations/${file}`)) as Record<string, Record<string, string>>;
    for (const [language, words] of Object.entries(json)) tables[language] = words;
  }
  return tables;
}

/** Each language's lookup order before English, as fallbackLanguages() gives it. */
export function languageOrder(code: string) {
  return fallbackLanguages(code).filter(c => c !== 'en' && c !== code);
}

const kotlinString = (s: string) => JSON.stringify(s).replace(/\$/g, '\\$');

export function languagesKotlin() {
  const lines = [kotlinHeader('DS1/0-face/languages.ts'), 'package com.designsystem1.ds1', '', '/** Every language Design system 1 knows, in the order pickers show them. */', 'enum class DS1Language(', '    /** The code, as the web writes it (`pt-BR`). */', '    val code: String,', '    /** The name in English. */', '    val label: String,', '    /** The name in the language itself, as a picker shows it. */', '    val nativeLabel: String,', '    /** Other tags that mean this language, lower case. */', '    val aliases: List<String>,', '    /** The languages a missing word is looked up in, nearest first, before English. */', '    val related: List<String>,', ') {'];
  for (const code of LANGUAGES) {
    const m = LANGUAGE_METADATA[code];
    const name = code === 'pt-BR' ? 'PtBR' : code[0].toUpperCase() + code.slice(1);
    lines.push(`    ${name}(${kotlinString(code)}, ${kotlinString(m.label)}, ${kotlinString(m.nativeLabel)}, listOf(${m.aliases.map(kotlinString).join(', ')}), listOf(${languageOrder(code).map(kotlinString).join(', ')})),`);
  }
  lines.push('    ;', '}', '');
  return lines.join('\n');
}

export function wordsKotlin() {
  const tables = sharedWordTables();
  const lines = [kotlinHeader('DS1/0-face/translations'), 'package com.designsystem1.ds1', '', '/** The words every product shares, by language, keyed by the English words. */', 'internal object DS1SharedWords {', '    val tables: Map<String, Map<String, String>> by lazy {', '        mapOf(', ...Object.keys(tables).map(l => `            ${kotlinString(l)} to ${swiftName(l)}Words(),`), '        )', '    }', ''];
  // One function a language keeps each method well inside the JVM's size limit.
  for (const [language, words] of Object.entries(tables)) {
    lines.push(`    private fun ${swiftName(language)}Words() = mapOf(`);
    for (const [key, value] of Object.entries(words)) lines.push(`        ${kotlinString(key)} to ${kotlinString(value)},`);
    lines.push('    )', '');
  }
  lines.push('}', '');
  return lines.join('\n');
}

/** Every generated Kotlin file, by its path in the repository. */
export function androidTokenFiles(): Record<string, string> {
  return {
    [`${androidGenerated}/Palette.kt`]: paletteKotlin(),
    [`${androidGenerated}/Metrics.kt`]: metricsKotlin(),
    [`${androidGenerated}/Icons.kt`]: iconsKotlin(),
    [`${androidGenerated}/Languages.kt`]: languagesKotlin(),
    [`${androidGenerated}/Words.kt`]: wordsKotlin(),
  };
}

/* The Swift package's languages and shared words, as the Kotlin package's. */

const swiftString = (s: string) => JSON.stringify(s).replace(/\\u([0-9a-f]{4})/gi, (_, h) => `\\u{${h}}`);

export function languagesSwift() {
  const lines = [header('DS1/0-face/languages.ts'), '/// Every language Design system 1 knows, in the order pickers show them.', 'public enum DS1Language: String, CaseIterable, Sendable {'];
  const cases: string[] = [];
  for (const code of LANGUAGES) {
    const name = code === 'pt-BR' ? 'ptBR' : code;
    cases.push(name);
    lines.push(name === code ? `    case ${identifier(name)}` : `    case ${identifier(name)} = ${swiftString(code)}`);
  }
  const prop = (label: string, type: string, doc: string, value: (code: (typeof LANGUAGES)[number]) => string) => {
    lines.push('', `    /// ${doc}`, `    public var ${label}: ${type} {`, '        switch self {');
    LANGUAGES.forEach((code, i) => lines.push(`        case .${identifier(cases[i])}: ${value(code)}`));
    lines.push('        }', '    }');
  };
  prop('code', 'String', 'The code, as the web writes it (`pt-BR`).', c => swiftString(c));
  prop('label', 'String', 'The name in English.', c => swiftString(LANGUAGE_METADATA[c].label));
  prop('nativeLabel', 'String', 'The name in the language itself, as a picker shows it.', c => swiftString(LANGUAGE_METADATA[c].nativeLabel));
  prop('aliases', '[String]', 'Other tags that mean this language, lower case.', c => `[${LANGUAGE_METADATA[c].aliases.map(swiftString).join(', ')}]`);
  prop('related', '[String]', 'The languages a missing word is looked up in, nearest first, before English.', c => `[${languageOrder(c).map(swiftString).join(', ')}]`);
  lines.push('}', '');
  return lines.join('\n');
}

export function wordsSwift() {
  const tables = sharedWordTables();
  const lines = [header('DS1/0-face/translations'), '/// The words every product shares, by language, keyed by the English words.', 'enum DS1SharedWords {', '    static let tables: [String: [String: String]] = ['];
  for (const language of Object.keys(tables)) lines.push(`        ${swiftString(language)}: ${swiftName(language)}Words,`);
  lines.push('    ]', '');
  for (const [language, words] of Object.entries(tables)) {
    lines.push(`    private static let ${swiftName(language)}Words: [String: String] = [`);
    for (const [key, value] of Object.entries(words)) lines.push(`        ${swiftString(key)}: ${swiftString(value)},`);
    lines.push('    ]', '');
  }
  lines.push('}', '');
  return lines.join('\n');
}
